#include <stddef.h>
#include <new>

class my_alloc
{
public:
  static void *allocate(size_t);
  static void deallocate(void *, size_t);
};

template <class T>
class my_allocator
{
public:
  typedef size_t size_type;
  typedef ptrdiff_t difference_type;
  typedef T *pointer;
  typedef const T *const_pointer;
  typedef T &reference;
  typedef const T &const_reference;
  typedef T value_type;

  template <class U> struct rebind { typedef my_allocator<U> other; };

  my_allocator() throw() {}
  my_allocator(const my_allocator &) throw() {}
  template <class U> my_allocator(const my_allocator<U> &) throw() {}
  ~my_allocator() throw() {}

  pointer address(reference x) const { return &x; }
  const_pointer address(const_reference x) const { return &x; }
  pointer allocate(size_type n, const void * = 0)
  {
    return n != 0 ? static_cast<pointer>(my_alloc::allocate(n * sizeof(T))) : 0;
  }
  void deallocate(pointer p, size_type n)
  {
    my_alloc::deallocate(p, n * sizeof(T));
  }
  size_type max_size() const throw() { return size_t(-1) / sizeof(T); }
  void construct(pointer p, const T &value) { new(p) T(value); }
  void destroy(pointer p) { p->~T(); }
};

template <class T, class U>
inline bool operator==(const my_allocator<T> &, const my_allocator<U> &) { return true; }
template <class T, class U>
inline bool operator!=(const my_allocator<T> &, const my_allocator<U> &) { return false; }

#include <vector>

class ai_polypath_cell;

template void vector<ai_polypath_cell *, my_allocator<ai_polypath_cell *> >::_M_insert_aux(
  ai_polypath_cell **, ai_polypath_cell *const &);
